corpus_block("test-draw-key.R: keys can communicate their size", {
  draw_key_dummy <- function(data, params, size) {
      grob <- circleGrob(r = unit(1, "cm"))
      attr(grob, "width")  <- 2
      attr(grob, "height") <- 2
      grob
    }
  .plot("test-draw-key.R: keys can communicate their size #1", ggplot(mtcars, aes(mpg, wt, colour = factor(cyl))) + geom_point(key_glyph = draw_key_dummy))
})

corpus_block("test-draw-key.R: horizontal key glyphs work", {
  df <- data.frame(
      middle = 1:2,
      lower = 0:1,
      upper = 2:3,
      min = -1:0,
      max = 3:4,
      group1 = c("a","b"),
      group2 = c("c","d")
    )
  .plot("test-draw-key.R: horizontal key glyphs work #1", p <- ggplot(df, aes(
      x = middle,
      xmiddle = middle,
      xlower = lower,
      xupper = upper,
      xmin = min,
      xmax = max
    )))
  .plot("test-draw-key.R: horizontal key glyphs work #2", p + geom_boxplot(aes(y = group1, color = group1), stat = "identity") + geom_crossbar(aes(y = group2, 
      fill = group2)) + guides(color = guide_legend(order = 1)))
  .plot("test-draw-key.R: horizontal key glyphs work #3", p + geom_linerange(aes(y = group1, color = group1)) + geom_pointrange(aes(y = group2, 
      shape = group2)) + guides(color = guide_legend(order = 1)))
})

